CREATE TABLE instrument( id INTEGER PRIMARY KEY, symbol TEXT NOT NULL UNIQUE, name TEXT, kite_token INTEGER);
CREATE TABLE sw_config( user_id INTEGER PRIMARY KEY, sleeve_capital_inr NUMERIC NOT NULL DEFAULT 0, risk_per_trade_pct NUMERIC NOT NULL DEFAULT 0.500, max_position_pct NUMERIC NOT NULL DEFAULT 20.00, max_open_positions INTEGER NOT NULL DEFAULT 10, or_window_minutes INTEGER NOT NULL DEFAULT 5, stop_mode TEXT NOT NULL DEFAULT 'LOW_OF_DAY', adr_min_pct NUMERIC NOT NULL DEFAULT 4.00, turnover_min_inr NUMERIC NOT NULL DEFAULT 50000000, price_min NUMERIC NOT NULL DEFAULT 20.00, exposure_level INTEGER NOT NULL DEFAULT 0, first_live_sessions_left INTEGER NOT NULL DEFAULT 5, sleeve_peak_inr NUMERIC, drawdown_pct NUMERIC NOT NULL DEFAULT 0, drawdown_locked BOOLEAN NOT NULL DEFAULT false, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_by TEXT, CHECK (first_live_sessions_left >= 0), CHECK (exposure_level >= 0 AND exposure_level <= 3));
CREATE TABLE sw_market_daily( user_id INTEGER NOT NULL, date TEXT NOT NULL, constituent_count INTEGER NOT NULL DEFAULT 0, pct_up_strong_1m NUMERIC, pct_new_52w_high NUMERIC, pct_above_ma_slow NUMERIC, index_slug TEXT, index_close NUMERIC, index_ma_fast NUMERIC, index_ma_slow NUMERIC, gate TEXT NOT NULL, exposure_level INTEGER NOT NULL DEFAULT 0, max_open_positions INTEGER NOT NULL, max_exposure_pct NUMERIC NOT NULL, new_entries_allowed BOOLEAN NOT NULL, parabolic_count INTEGER NOT NULL DEFAULT 0, detail TEXT, drawdown_pct NUMERIC NOT NULL DEFAULT 0, drawdown_locked BOOLEAN NOT NULL DEFAULT false, provisional BOOLEAN NOT NULL DEFAULT false, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (user_id, date), CHECK (gate IN ('GREEN', 'AMBER', 'RED')), CHECK (exposure_level >= 0 AND exposure_level <= 3));
CREATE TABLE sw_setup_daily( user_id INTEGER NOT NULL, date TEXT NOT NULL, instrument_id INTEGER NOT NULL REFERENCES instrument(id), setup TEXT NOT NULL, status TEXT NOT NULL, score NUMERIC NOT NULL, close NUMERIC, trigger NUMERIC, stop_ref NUMERIC, pivot_high NUMERIC, adj_factor NUMERIC, adr_pct NUMERIC, prior_move_pct NUMERIC, base_depth_pct NUMERIC, tightness_adr NUMERIC, dryup_ratio NUMERIC, dist_ma_fast_pct NUMERIC, dist_ma_slow_pct NUMERIC, rvol NUMERIC, gap_pct NUMERIC, turnover_avg INTEGER, base_bars INTEGER, up_streak INTEGER, locked_upper_circuit BOOLEAN NOT NULL DEFAULT false, sector_slug TEXT, listed_within_2y BOOLEAN NOT NULL DEFAULT false, pipeline_run_id INTEGER, provisional BOOLEAN NOT NULL DEFAULT false, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (user_id, date, instrument_id, setup), CHECK (setup IN ('FLAG', 'EP', 'PARABOLIC_SHORT')));
CREATE TABLE sw_plan( id INTEGER PRIMARY KEY AUTOINCREMENT, plan_id TEXT NOT NULL UNIQUE, user_id INTEGER NOT NULL, as_of TEXT NOT NULL, source TEXT NOT NULL, built_at TEXT NOT NULL, expires_at TEXT NOT NULL, plan_hash TEXT NOT NULL, gate TEXT NOT NULL, exposure_level INTEGER NOT NULL, total_risk_inr NUMERIC NOT NULL DEFAULT 0, total_new_exposure_inr NUMERIC NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK (gate IN ('GREEN', 'AMBER', 'RED')), CHECK (source IN ('EOD_PREVIEW', 'MORNING', 'SIGNAL')));
CREATE TABLE sw_plan_line( id INTEGER PRIMARY KEY AUTOINCREMENT, plan_id INTEGER NOT NULL REFERENCES sw_plan(id), user_id INTEGER NOT NULL, kind TEXT NOT NULL, instrument_id INTEGER NOT NULL REFERENCES instrument(id), setup TEXT, quantity INTEGER NOT NULL DEFAULT 0, trigger NUMERIC, stop NUMERIC, risk_inr NUMERIC NOT NULL DEFAULT 0, position_value NUMERIC NOT NULL DEFAULT 0, trail TEXT, note TEXT, state TEXT NOT NULL DEFAULT 'PROPOSED', client_id TEXT NOT NULL UNIQUE, journal_ref TEXT, position_id INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK (kind IN ('BUY_ON_TRIGGER', 'SELL_AT_OPEN', 'RAISE_GTT_STOP', 'PENDING_RANGE')), CHECK (state IN ('PROPOSED','CONFIRMED','SENT','FILLED','REJECTED','EXPIRED','SKIPPED')));
CREATE TABLE sw_plan_skip( id INTEGER PRIMARY KEY AUTOINCREMENT, plan_id INTEGER NOT NULL REFERENCES sw_plan(id), user_id INTEGER NOT NULL, instrument_id INTEGER, symbol TEXT NOT NULL, reason TEXT NOT NULL, detail TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sw_watch( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, instrument_id INTEGER NOT NULL REFERENCES instrument(id), setup TEXT NOT NULL, source TEXT NOT NULL, added_on TEXT NOT NULL, expires_on TEXT, trigger NUMERIC, stop_ref NUMERIC, setup_daily_date TEXT, note TEXT, catalyst TEXT, state TEXT NOT NULL DEFAULT 'WATCHING', score NUMERIC, adr_pct NUMERIC, focus BOOLEAN NOT NULL DEFAULT false, reconfirmed_on TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sw_signal( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, watch_id INTEGER REFERENCES sw_watch(id), instrument_id INTEGER NOT NULL REFERENCES instrument(id), setup TEXT NOT NULL, session_date TEXT NOT NULL, raised_at TEXT NOT NULL, state TEXT NOT NULL, or_window_minutes INTEGER, range_high NUMERIC, range_low NUMERIC, low_of_day NUMERIC, last_price NUMERIC, entry NUMERIC, stop NUMERIC, plan_line_id INTEGER REFERENCES sw_plan_line(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sw_position( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, broker_account_id INTEGER, instrument_id INTEGER NOT NULL REFERENCES instrument(id), setup TEXT NOT NULL, entry_date TEXT NOT NULL, entry_avg NUMERIC NOT NULL, quantity_entered INTEGER NOT NULL, initial_stop NUMERIC NOT NULL, stop NUMERIC NOT NULL, gtt_id TEXT, gtt_trigger NUMERIC, gtt_armed_at TEXT, trail TEXT NOT NULL, partial_done BOOLEAN NOT NULL DEFAULT false, partial_date TEXT, quantity_open INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'OPEN', closed_on TEXT, exit_avg NUMERIC, close_reason TEXT, r_multiple NUMERIC, pnl_inr NUMERIC, simulated BOOLEAN NOT NULL DEFAULT true, half_risk BOOLEAN NOT NULL DEFAULT false, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK (setup IN ('FLAG', 'EP', 'PARABOLIC_SHORT')), CHECK (state IN ('OPEN', 'PARTIAL', 'CLOSED')), CHECK (trail IN ('MA10', 'MA20')), CHECK (initial_stop < entry_avg), CHECK (quantity_open <= quantity_entered), CHECK (quantity_open >= 0), CHECK (stop >= initial_stop));
CREATE TABLE sw_fill( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, position_id INTEGER NOT NULL REFERENCES sw_position(id), side TEXT NOT NULL, quantity INTEGER NOT NULL, price NUMERIC NOT NULL, filled_at TEXT NOT NULL, journal_ref TEXT, simulated BOOLEAN NOT NULL DEFAULT true, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK (side IN ('BUY', 'SELL')), CHECK (quantity > 0));
CREATE TABLE sw_session( user_id INTEGER NOT NULL, session_date TEXT NOT NULL, mode TEXT NOT NULL, monitor_ran BOOLEAN NOT NULL DEFAULT false, plan_ids TEXT, signals INTEGER NOT NULL DEFAULT 0, confirms INTEGER NOT NULL DEFAULT 0, fills INTEGER NOT NULL DEFAULT 0, manage_actions INTEGER NOT NULL DEFAULT 0, notes TEXT, first_live_counted BOOLEAN NOT NULL DEFAULT false, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (user_id, session_date), CHECK (mode IN ('DRY_RUN', 'LIVE')));
CREATE TABLE sw_catalyst( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, instrument_id INTEGER NOT NULL REFERENCES instrument(id), headline TEXT NOT NULL, published_at TEXT, url TEXT NOT NULL, source TEXT NOT NULL, earnings_date TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (user_id, instrument_id, url), CHECK (source IN ('NSE_ANNOUNCEMENT', 'NSE_EVENT_CALENDAR')));
CREATE TABLE sw_scan_run( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, requested_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, started_at TEXT, finished_at TEXT, session_date TEXT, provisional BOOLEAN NOT NULL DEFAULT false, status TEXT NOT NULL DEFAULT 'QUEUED', detail TEXT, error TEXT, task_id TEXT, CHECK (status IN ('QUEUED', 'RUNNING', 'DONE', 'FAILED')));
CREATE TABLE lv_protection_issue ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, sleeve TEXT NOT NULL, position_id INTEGER NOT NULL, symbol TEXT NOT NULL, kind TEXT NOT NULL, detail TEXT NOT NULL, seen_at TEXT NOT NULL, resolved_at TEXT);
